using Microsoft.ML;
using Microsoft.ML.Data;
using System.ComponentModel.DataAnnotations;

// Data classes for ML.NET
public class CustomerData
{
    [LoadColumn(0)]
    public float Age { get; set; }

    [LoadColumn(1)]
    public float Income { get; set; }

    [LoadColumn(2)]
    public string Region { get; set; } = string.Empty;

    [LoadColumn(3)]
    public float PurchaseHistory { get; set; }

    [LoadColumn(4)]
    public string Churned { get; set; } = string.Empty;
}

public class ChurnPrediction
{
    [ColumnName("PredictedLabel")]
    public bool WillChurn { get; set; }

    [ColumnName("Probability")]
    public float Probability { get; set; }
}

public class PredictRequest
{
    public float Age { get; set; }
    public float Income { get; set; }
    public string Region { get; set; } = string.Empty;
    public float PurchaseHistory { get; set; }
}

// Initialize ML.NET
var mlContext = new MLContext(seed: 0);

// Load the CSV data
var dataPath = Path.Combine(Directory.GetCurrentDirectory(), "Data", "customers.csv");
var dataView = mlContext.Data.LoadFromTextFile<CustomerData>(
    path: dataPath,
    hasHeader: true,
    separatorChar: ','
);

// Create a pipeline
var pipeline = mlContext.Transforms
    // Map the Churned string column (Yes/No) to a key for the label
    .Conversion.MapValueToKey("Label", nameof(CustomerData.Churned), 
        keyData: mlContext.Data.LoadFromTextFile<CustomerData>(dataPath, hasHeader: true, separatorChar: ','))
    // One-hot encode the Region categorical column
    .Append(mlContext.Transforms.Categorical.OneHotEncoding("RegionEncoded", nameof(CustomerData.Region)))
    // Concatenate all features into a single Features column
    .Append(mlContext.Transforms.Concatenate("Features", 
        nameof(CustomerData.Age), 
        nameof(CustomerData.Income), 
        "RegionEncoded", 
        nameof(CustomerData.PurchaseHistory)))
    // Use FastTree for binary classification
    .Append(mlContext.BinaryClassification.Trainers.FastTree(
        labelColumnName: "Label",
        featureColumnName: "Features"
    ));

// Train the model
var trainedModel = pipeline.Fit(dataView);

// Create prediction engine
var predictionEngine = mlContext.Model.CreatePredictionEngine<CustomerData, ChurnPrediction>(trainedModel);

var builder = WebApplication.CreateBuilder(args);
var app = builder.Build();

// GET endpoint: API description
app.MapGet("/", () => new
{
    message = "ML.NET Churn Prediction API",
    endpoints = new[]
    {
        new { method = "GET", path = "/", description = "API description" },
        new { method = "POST", path = "/predict", description = "Predict customer churn", 
            example = new { Age = 25, Income = 45000, Region = "East", PurchaseHistory = 12 } }
    }
});

// POST endpoint: Churn prediction
app.MapPost("/predict", (PredictRequest request) =>
{
    var customerData = new CustomerData
    {
        Age = request.Age,
        Income = request.Income,
        Region = request.Region,
        PurchaseHistory = request.PurchaseHistory,
        Churned = "No" // Placeholder; not used for prediction
    };

    var prediction = predictionEngine.Predict(customerData);

    return new
    {
        willChurn = prediction.WillChurn,
        probability = prediction.Probability
    };
});

app.Run();

